package br.com.conectatea.sessao.domain; import br.com.conectatea.shared.domain.*; import jakarta.persistence.*; import java.time.OffsetDateTime; @Entity @Table(name="sessoes") public class Sessao extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="data_hora") private OffsetDateTime dataHora; private int duracao; @Enumerated(EnumType.STRING) private StatusSessao status; @Enumerated(EnumType.STRING) private TipoSessao tipo; @Column(columnDefinition="text") private String descricao; @Column(name="observacao_privada",columnDefinition="text") private String observacoes; @Enumerated(EnumType.STRING) private ModalidadeSessao modalidade=ModalidadeSessao.PRESENCIAL; @Column(name="local_instrucoes") private String localInstrucoes; @Column(columnDefinition="text") private String objetivos; @Column(name="anotacao_id") private Long anotacaoId; @Column(name="crianca_id") private Long criancaId; @Column(name="profissional_id") private Long profissionalId; protected Sessao(){} public Sessao(OffsetDateTime d,int duration,TipoSessao t,String desc,String obs,Long child,Long prof){dataHora=d;duracao=duration;tipo=t;descricao=desc;observacoes=obs;criancaId=child;profissionalId=prof;status=StatusSessao.AGENDADA;} public Long getId(){return id;} public OffsetDateTime getDataHora(){return dataHora;} public int getDuracao(){return duracao;} public StatusSessao getStatus(){return status;} public TipoSessao getTipo(){return tipo;} public String getDescricao(){return descricao;} public String getObservacoes(){return observacoes;} public ModalidadeSessao getModalidade(){return modalidade;} public String getLocalInstrucoes(){return localInstrucoes;} public String getObjetivos(){return objetivos;} public Long getAnotacaoId(){return anotacaoId;} public Long getCriancaId(){return criancaId;} public Long getProfissionalId(){return profissionalId;} public void update(OffsetDateTime d,int du,TipoSessao t,String de,String o){if(status!=StatusSessao.AGENDADA)throw new BusinessRuleException("SESSION_FINAL","Sessão finalizada exige correção com motivo");dataHora=d;duracao=du;tipo=t;descricao=de;observacoes=o;} public void details(ModalidadeSessao m,String local,String goals,Long note){modalidade=m==null?ModalidadeSessao.PRESENCIAL:m;localInstrucoes=local;objetivos=goals;anotacaoId=note;} public void status(StatusSessao s){if(status!=StatusSessao.AGENDADA)throw new BusinessRuleException("INVALID_SESSION_TRANSITION","Estado final exige fluxo de correção");if(s==StatusSessao.NAO_COMPARECEU&&OffsetDateTime.now().isBefore(dataHora))throw new BusinessRuleException("NO_SHOW_BEFORE_START","Não comparecimento somente após o horário");if(s!=StatusSessao.REALIZADA&&s!=StatusSessao.CANCELADA&&s!=StatusSessao.NAO_COMPARECEU)throw new BusinessRuleException("INVALID_SESSION_TRANSITION","Transição não permitida");status=s;} public void correct(StatusSessao s){if(status==StatusSessao.AGENDADA)throw new BusinessRuleException("SESSION_NOT_FINAL","Use a transição normal");if(s!=StatusSessao.REALIZADA&&s!=StatusSessao.CANCELADA&&s!=StatusSessao.NAO_COMPARECEU)throw new BusinessRuleException("INVALID_SESSION_TRANSITION","Estado final inválido");status=s;} }
